import Constants from "expo-constants";
import * as Linking from "expo-linking";
import * as SecureStore from "expo-secure-store";
import * as WebBrowser from "expo-web-browser";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Feather } from "@expo/vector-icons";
import { Gesture, GestureDetector, GestureHandlerRootView } from "react-native-gesture-handler";
import Animated, { runOnJS, useAnimatedStyle, useSharedValue, withSpring, withTiming } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useColorScheme } from "react-native";
import {
  ActivityIndicator, Alert, Image, KeyboardAvoidingView, Modal, Platform, Pressable, ScrollView,
  StyleSheet, Text, TextInput, View,
} from "react-native";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

WebBrowser.maybeCompleteAuthSession();

type User = { user_id: string; email: string; name: string; picture?: string | null };
type Entry = { date: string; value?: number | null; completed: boolean };
type Habit = { habit_id: string; name: string; icon: string; habit_type: "boolean" | "measurable"; target?: number | null; unit?: string | null; hidden?: boolean; entries: Entry[] };
type ThemeMode = "system" | "light" | "dark";

const API_ROOT = `${Constants.expoConfig?.extra?.EXPO_BACKEND_URL || Constants.expoConfig?.extra?.backendUrl || process.env.EXPO_BACKEND_URL || process.env.EXPO_PUBLIC_BACKEND_URL || ""}/api`;
const TICK_IT_LOGO = "data:image/jpeg;base64,";
const TOKEN_KEY = "rhythm_session_token";
const THEME_KEY = "rhythm_theme_mode";
const iconChoices = ["droplet", "activity", "book-open", "moon", "coffee", "heart", "sun", "check-circle", "music", "smile"];
const lightColors = { bg: "#FAF8F5", card: "#FFFFFF", surface: "#F1EEE9", raised: "#E6E2DC", text: "#1C1C1E", muted: "#636366", border: "#E5E1DB", brand: "#4A6B5D", pale: "#E4ECE8", red: "#D96A5E", yellow: "#E9B66B", white: "#FFFFFF" };
const darkColors = { bg: "#171A18", card: "#222723", surface: "#2B332E", raised: "#39433D", text: "#F5F3EF", muted: "#A8B0AA", border: "#3D4841", brand: "#91B6A3", pale: "#31463B", red: "#EF8274", yellow: "#E7B56D", white: "#18201B" };

const storage = {
  async getToken() { return Platform.OS === "web" ? (typeof localStorage !== "undefined" ? localStorage.getItem(TOKEN_KEY) : null) : SecureStore.getItemAsync(TOKEN_KEY); },
  async setToken(token: string) { if (Platform.OS === "web") localStorage.setItem(TOKEN_KEY, token); else await SecureStore.setItemAsync(TOKEN_KEY, token); },
  async clearToken() { if (Platform.OS === "web") localStorage.removeItem(TOKEN_KEY); else await SecureStore.deleteItemAsync(TOKEN_KEY); },
};

async function api(path: string, options: RequestInit = {}, token?: string | null) {
  const response = await fetch(`${API_ROOT}${path}`, {
    ...options,
    headers: { "Content-Type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(options.headers || {}) },
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.detail || "Something went wrong");
  return body;
}

function dateKey(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function monthLabel(date: Date) { return date.toLocaleDateString("en-US", { month: "long", year: "numeric" }); }
function monthDays(date: Date) { return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate(); }
function startOfWeek(date: Date) { const d = new Date(date.getFullYear(), date.getMonth(), date.getDate()); const day = d.getDay(); const offset = day === 0 ? 6 : day - 1; d.setDate(d.getDate() - offset); return d; }
function weekLabel(date: Date) { const start = startOfWeek(date); const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 6); const fmt = (d: Date) => d.toLocaleDateString("en-US", { month: "short", day: "numeric" }); return start.getFullYear() === end.getFullYear() ? `${fmt(start)} – ${fmt(end)}` : `${fmt(start)}, ${start.getFullYear()} – ${fmt(end)}, ${end.getFullYear()}`; }
function progress(value: number | null | undefined, target: number | null | undefined) { return target ? Math.min(1.25, Math.max(0, (value || 0) / target)) : 0; }
function greenFor(value: number | null | undefined, target: number | null | undefined, colors: typeof lightColors) {
  const ratio = progress(value, target);
  if (ratio === 0) return colors.raised;
  if (ratio < 0.5) return "#D6E9D8";
  if (ratio < 0.8) return "#A9D4AF";
  if (ratio < 1) return "#71B981";
  return "#3E9561";
}

function AuthScreen({ onAuthenticated, colors }: { onAuthenticated: (data: { user: User; session_token: string }) => void; colors: typeof lightColors }) {
  const insets = useSafeAreaInsets();
  const [mode, setMode] = useState<"login" | "signup">("login");
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [name, setName] = useState("");
  const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const processed = useRef(new Set<string>());
  const finishAuth = useCallback(async (data: { user: User; session_token: string }) => { await storage.setToken(data.session_token); onAuthenticated(data); }, [onAuthenticated]);
  const submit = async () => {
    setError(""); setBusy(true);
    try { const data = await api(`/auth/${mode === "login" ? "login" : "register"}`, { method: "POST", body: JSON.stringify({ email, password, name: mode === "signup" ? name : undefined }) }); await finishAuth(data); }
    catch (err) { setError(err instanceof Error ? err.message : "Authentication failed"); } finally { setBusy(false); }
  };
  const exchange = useCallback(async (url: string) => {
    const match = url.match(/[?#&]session_id=([^&#]+)/); if (!match || processed.current.has(match[1])) return false;
    processed.current.add(match[1]); setBusy(true); setError("");
    try { await finishAuth(await api("/auth/session", { method: "POST", body: JSON.stringify({ session_id: decodeURIComponent(match[1]) }) })); return true; }
    catch (err) { setError(err instanceof Error ? err.message : "Google sign-in failed"); return false; } finally { setBusy(false); }
  }, [finishAuth]);
  useEffect(() => {
    if (Platform.OS === "web" && typeof window !== "undefined") { const url = window.location.href; if (url.includes("session_id=")) exchange(url); }
  }, [exchange]);
  const google = async () => {
    setBusy(true); setError(""); let received: string | null = null;
    const listener = Linking.addEventListener("url", event => { received = event.url; });
    try {
      const redirect = Platform.OS === "web" ? `${window.location.origin}/` : Linking.createURL("");
      if (Platform.OS === "web") window.location.href = `https://auth.emergentagent.com/?redirect=${encodeURIComponent(redirect)}`;
      else { const result = await WebBrowser.openAuthSessionAsync(`https://auth.emergentagent.com/?redirect=${encodeURIComponent(redirect)}`, redirect); const url = result.type === "success" ? result.url : received || await Linking.getInitialURL(); if (url) await exchange(url); }
    } catch { setError("Google sign-in is unavailable right now"); setBusy(false); } finally { listener.remove(); }
  };
  return <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={[styles.authRoot, { backgroundColor: colors.bg, paddingTop: insets.top + 16, paddingBottom: insets.bottom + 24 }]}>
    <ScrollView contentContainerStyle={styles.authContent} keyboardShouldPersistTaps="handled">
      <View style={styles.authLogoWrap}><Image testID="tick-it-logo-auth" source={{ uri: TICK_IT_LOGO }} style={styles.authLogo} resizeMode="cover" /></View>
      <View style={[styles.authPanel, { backgroundColor: colors.card, borderColor: colors.border }]}>
        <View style={styles.authSwitch}><Pressable testID="auth-mode-login" onPress={() => setMode("login")} style={[styles.switchButton, mode === "login" && { backgroundColor: colors.surface }]}><Text style={[styles.switchText, { color: mode === "login" ? colors.text : colors.muted }]}>Sign in</Text></Pressable><Pressable testID="auth-mode-signup" onPress={() => setMode("signup")} style={[styles.switchButton, mode === "signup" && { backgroundColor: colors.surface }]}><Text style={[styles.switchText, { color: mode === "signup" ? colors.text : colors.muted }]}>Create account</Text></Pressable></View>
        {mode === "signup" && <TextInput testID="auth-name" placeholder="Your name" placeholderTextColor={colors.muted} value={name} onChangeText={setName} style={[styles.input, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} />}
        <TextInput testID="auth-email" autoCapitalize="none" keyboardType="email-address" placeholder="Email address" placeholderTextColor={colors.muted} value={email} onChangeText={setEmail} style={[styles.input, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} />
        <TextInput testID="auth-password" secureTextEntry placeholder="Password (8+ characters)" placeholderTextColor={colors.muted} value={password} onChangeText={setPassword} style={[styles.input, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} />
        {!!error && <Text style={[styles.error, { color: colors.red }]}>{error}</Text>}
        <Pressable testID="auth-submit" disabled={busy} onPress={submit} style={({ pressed }) => [styles.primaryButton, { backgroundColor: colors.brand, opacity: pressed || busy ? 0.72 : 1 }]}><Text style={styles.primaryText}>{busy ? "Working…" : mode === "login" ? "Continue" : "Create my account"}</Text>{busy && <ActivityIndicator color="#FFF" />}</Pressable>
        <View style={styles.orRow}><View style={[styles.orLine, { backgroundColor: colors.border }]} /><Text style={[styles.orText, { color: colors.muted }]}>or</Text><View style={[styles.orLine, { backgroundColor: colors.border }]} /></View>
        <Pressable testID="auth-google" disabled={busy} onPress={google} style={[styles.googleButton, { borderColor: colors.border }]}><Text style={[styles.googleG, { color: colors.brand }]}>G</Text><Text style={[styles.googleText, { color: colors.text }]}>Continue with Google</Text></Pressable>
      </View>
      <Text style={[styles.footNote, { color: colors.muted }]}>Your habits stay private and synced to your account.</Text>
    </ScrollView>
  </KeyboardAvoidingView>;
}

function DayCell({ habit, day, entry, colors, onPress, size = "month" }: { habit: Habit; day: number; entry?: Entry; colors: typeof lightColors; onPress: () => void; size?: "month" | "week" }) {
  const ratio = habit.habit_type === "boolean" ? (entry?.completed ? 1 : 0) : progress(entry?.value, habit.target);
  const bg = habit.habit_type === "boolean" ? (entry?.completed ? colors.brand : entry ? colors.red : colors.raised) : greenFor(entry?.value, habit.target, colors);
  const burst = useSharedValue(0);
  const [showBurst, setShowBurst] = useState(false);
  const burstStyle = useAnimatedStyle(() => ({ opacity: burst.value, transform: [{ scale: 1 + burst.value * 1.4 }] }));
  const isWeek = size === "week";
  const tap = () => {
    if (habit.habit_type === "boolean" && !entry?.completed) {
      setShowBurst(true);
      burst.value = 1;
      burst.value = withTiming(0, { duration: 520 }, finished => { if (finished) runOnJS(setShowBurst)(false); });
    }
    onPress();
  };
  return <Pressable testID={`day-cell-${habit.habit_id}-${day}`} accessibilityLabel={`${habit.name}, day ${day}, ${habit.habit_type === "boolean" ? (entry?.completed ? "done" : entry ? "not done" : "no entry") : `${Math.round(ratio * 100)} percent`}`} onPress={tap} style={({ pressed }) => [styles.dayCell, isWeek ? { flex: 1, height: 52, minHeight: 52, aspectRatio: undefined, borderRadius: 10 } : { flex: 1, height: 30, minHeight: 30, aspectRatio: undefined }, { backgroundColor: bg, borderColor: ratio > 0 ? bg : colors.border, transform: [{ scale: pressed ? 0.88 : 1 }] }]}><Text style={[isWeek ? styles.weekDayNumber : styles.dayNumber, { color: ratio > 0.55 ? "#FFF" : colors.muted }]}>{day}</Text>{showBurst && <Animated.View pointerEvents="none" style={[{ position: "absolute", width: isWeek ? 44 : 28, height: isWeek ? 44 : 28 }, burstStyle]}><View style={{ position: "absolute", width: 4, height: 4, borderRadius: 2, backgroundColor: "#D48356", left: 2, top: 1 }} /><View style={{ position: "absolute", width: 4, height: 4, borderRadius: 2, backgroundColor: "#91B64A", right: 1, top: 3 }} /><View style={{ position: "absolute", width: 4, height: 4, borderRadius: 2, backgroundColor: "#F2B84B", left: 5, bottom: 2 }} /><View style={{ position: "absolute", width: 4, height: 4, borderRadius: 2, backgroundColor: "#4A6B5D", right: 4, bottom: 1 }} /></Animated.View>}</Pressable>;
}

function HabitCard({ habit, colors, month, onMonthChange, onDayPress, onReorder, isReordering, onHide, onDelete }: { habit: Habit; colors: typeof lightColors; month: Date; onMonthChange: (date: Date) => void; onDayPress: (date: Date) => void; onReorder: (delta: number) => void; isReordering: boolean; onHide: () => void; onDelete: () => void }) {
  const y = useSharedValue(0);
  const gesture = Gesture.Pan().activateAfterLongPress(350).onUpdate(e => { y.value = e.translationY; }).onEnd(e => { if (Math.abs(e.translationY) > 36) runOnJS(onReorder)(e.translationY > 0 ? 1 : -1); y.value = withSpring(0); });
  const animatedStyle = useAnimatedStyle(() => ({ transform: [{ translateY: y.value }] }));
  const entries = useMemo(() => new Map(habit.entries.map(entry => [entry.date, entry])), [habit.entries]);
  const [view, setView] = useState<"month" | "week">("month");
  const [weekAnchor, setWeekAnchor] = useState<Date>(() => startOfWeek(new Date()));
  const isDone = (entry?: Entry) => habit.habit_type === "boolean" ? !!entry?.completed : (entry?.value || 0) >= (habit.target || 1);
  const days = monthDays(month); const firstDay = new Date(month.getFullYear(), month.getMonth(), 1).getDay(); const mondayOffset = firstDay === 0 ? 6 : firstDay - 1;
  const weekStart = startOfWeek(weekAnchor);
  const weekDates = Array.from({ length: 7 }, (_, i) => new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + i));
  const completed = view === "month"
    ? Array.from({ length: days }, (_, i) => entries.get(dateKey(new Date(month.getFullYear(), month.getMonth(), i + 1)))).filter(isDone).length
    : weekDates.map(date => entries.get(dateKey(date))).filter(isDone).length;
  const totalUnits = view === "month" ? days : 7;
  const streak = (() => { let count = 0; const cursor = new Date(); while (count < 365) { const entry = entries.get(dateKey(cursor)); if (!isDone(entry)) break; count++; cursor.setDate(cursor.getDate() - 1); } return count; })();
  const cells = Array.from({ length: mondayOffset + days }, (_, index) => index < mondayOffset ? null : index - mondayOffset + 1);
  const prev = () => view === "month" ? onMonthChange(new Date(month.getFullYear(), month.getMonth() - 1, 1)) : setWeekAnchor(new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() - 7));
  const next = () => view === "month" ? onMonthChange(new Date(month.getFullYear(), month.getMonth() + 1, 1)) : setWeekAnchor(new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + 7));
  const weeks: (number | null)[][] = []; for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7)); while (weeks.length && weeks[weeks.length - 1].length < 7) weeks[weeks.length - 1].push(null);
  const [menuOpen, setMenuOpen] = useState(false);
  return <GestureDetector gesture={gesture}><Animated.View testID={`habit-card-${habit.habit_id}`} style={[styles.habitCard, { padding: 12, backgroundColor: colors.card, borderColor: isReordering ? colors.brand : colors.border }, animatedStyle]}>
    <View style={styles.cardTop}><View style={[styles.habitIcon, { backgroundColor: colors.pale }]}><Feather name={habit.icon as any} size={18} color={colors.brand} /></View><View style={styles.habitIdentity}><Text style={[styles.habitName, { color: colors.text }]} numberOfLines={1}>{habit.name}</Text><View style={styles.targetRow}><Text style={[styles.habitTarget, { color: colors.muted }]} numberOfLines={1}>{habit.habit_type === "boolean" ? "Daily practice" : `Target ${habit.target} ${habit.unit || "units"}`}</Text><View style={styles.streakInline}><Feather name="zap" size={12} color={colors.yellow} /><Text style={[styles.streakInlineText, { color: colors.text }]}>{streak}</Text></View></View></View><View style={styles.cardTopRight}><View style={[styles.viewToggle, { backgroundColor: colors.surface }]}><Pressable testID={`view-month-${habit.habit_id}`} onPress={() => setView("month")} style={[styles.viewOption, view === "month" && { backgroundColor: colors.card }]}><Text style={[styles.viewText, { color: view === "month" ? colors.text : colors.muted }]}>Month</Text></Pressable><Pressable testID={`view-week-${habit.habit_id}`} onPress={() => { setWeekAnchor(startOfWeek(new Date())); setView("week"); }} style={[styles.viewOption, view === "week" && { backgroundColor: colors.card }]}><Text style={[styles.viewText, { color: view === "week" ? colors.text : colors.muted }]}>Week</Text></Pressable></View><Pressable testID={`habit-more-${habit.habit_id}`} accessibilityLabel="Habit options" onPress={() => setMenuOpen(open => !open)} style={styles.moreButton}><Feather name="more-vertical" size={18} color={colors.muted} /></Pressable></View></View>
    <Modal transparent animationType="fade" visible={menuOpen} onRequestClose={() => setMenuOpen(false)}><Pressable style={styles.moreModalBackdrop} onPress={() => setMenuOpen(false)}><View style={[styles.morePopoverModal, { backgroundColor: colors.card, borderColor: colors.border }]}><Pressable testID={`habit-hide-${habit.habit_id}`} onPress={() => { setMenuOpen(false); onHide(); }} style={styles.moreItem}><Feather name="eye-off" size={16} color={colors.text} /><Text style={[styles.moreText, { color: colors.text }]}>Hide</Text></Pressable><View style={[styles.moreDivider, { backgroundColor: colors.border }]} /><Pressable testID={`habit-delete-${habit.habit_id}`} onPress={() => { setMenuOpen(false); onDelete(); }} style={styles.moreItem}><Feather name="trash-2" size={16} color={colors.red} /><Text style={[styles.moreText, { color: colors.red }]}>Delete</Text></Pressable></View></Pressable></Modal>
    <View style={[styles.monthRow, { marginTop: 8, marginBottom: 4 }]}><Pressable testID={`nav-prev-${habit.habit_id}`} accessibilityLabel={view === "month" ? "Previous month" : "Previous week"} onPress={prev} style={styles.iconButton}><Feather name="chevron-left" size={20} color={colors.text} /></Pressable><Text style={[styles.monthText, { color: colors.text }]}>{view === "month" ? monthLabel(month) : weekLabel(weekAnchor)}</Text><Pressable testID={`nav-next-${habit.habit_id}`} accessibilityLabel={view === "month" ? "Next month" : "Next week"} onPress={next} style={styles.iconButton}><Feather name="chevron-right" size={20} color={colors.text} /></Pressable></View>
    <View style={styles.weekLabels}>{["M", "T", "W", "T", "F", "S", "S"].map((label, index) => <Text key={`${label}${index}`} style={[styles.weekLabel, { color: colors.muted }]}>{label}</Text>)}</View>
    {view === "month"
      ? <View style={styles.calendarGrid}>{weeks.map((week, wi) => <View key={`w-${wi}`} style={styles.weekLine}>{week.map((day, di) => day ? <DayCell key={`d-${day}`} habit={habit} day={day} entry={entries.get(dateKey(new Date(month.getFullYear(), month.getMonth(), day)))} colors={colors} onPress={() => onDayPress(new Date(month.getFullYear(), month.getMonth(), day))} /> : <View key={`e-${wi}-${di}`} style={styles.dayCellEmpty} />)}</View>)}</View>
      : <View style={styles.weekRow}>{weekDates.map(date => <DayCell key={dateKey(date)} habit={habit} day={date.getDate()} entry={entries.get(dateKey(date))} colors={colors} onPress={() => onDayPress(date)} size="week" />)}</View>}
    <View style={[styles.cardFooter, { borderTopColor: colors.border, marginTop: 10, paddingTop: 8 }]}><Text style={[styles.statStrong, { color: colors.text, marginRight: 10 }]}>{completed}/{totalUnits} <Text style={[styles.statLabel, { color: colors.muted }]}>completed</Text></Text><Text style={[styles.statStrong, { color: colors.brand, marginRight: 10 }]}>{Math.round((completed / totalUnits) * 100)}%</Text><View style={styles.dragHint}><Feather name="move" size={14} color={colors.muted} /><Text style={[styles.dragText, { color: colors.muted }]}>Hold to move</Text></View></View>
  </Animated.View></GestureDetector>;
}

function EntryModal({ habit, date, colors, onClose, onSave }: { habit: Habit; date: Date; colors: typeof lightColors; onClose: () => void; onSave: (value: number | boolean) => Promise<void> }) {
  const currentDate = dateKey(date); const current = habit.entries.find(entry => entry.date === currentDate); const [value, setValue] = useState(habit.habit_type === "measurable" ? String(current?.value ?? "") : ""); const [busy, setBusy] = useState(false);
  const save = async () => { setBusy(true); try { await onSave(habit.habit_type === "boolean" ? !current?.completed : Number(value)); } finally { setBusy(false); } };
  const dayLabel = date.toLocaleDateString("en-US", { weekday: "short", month: "long", day: "numeric" });
  return <Modal transparent animationType="slide" visible onRequestClose={onClose}><View style={[styles.modalBackdrop, { backgroundColor: "rgba(0,0,0,.38)" }]}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: 24 }]}><View style={[styles.sheetHandle, { backgroundColor: colors.border }]} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetEyebrow, { color: colors.brand }]}>{habit.name.toUpperCase()}</Text><Text style={[styles.sheetTitle, { color: colors.text }]}>{dayLabel}</Text></View><Pressable testID="entry-close" onPress={onClose} style={styles.iconButton}><Feather name="x" size={22} color={colors.text} /></Pressable></View><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ paddingBottom: 16 }}>{habit.habit_type === "boolean" ? <View style={[styles.statusBox, { backgroundColor: current?.completed ? colors.pale : colors.surface }]}><Feather name={current?.completed ? "check-circle" : "circle"} size={24} color={current?.completed ? colors.brand : colors.muted} /><Text style={[styles.statusText, { color: colors.text }]}>{current?.completed ? "Done for this day" : "Mark this day done"}</Text></View> : <><Text style={[styles.fieldLabel, { color: colors.muted }]}>Actual value · target {habit.target} {habit.unit}</Text><View style={styles.measureRow}><TextInput testID="entry-value" autoFocus keyboardType="decimal-pad" value={value} onChangeText={setValue} placeholder="0" placeholderTextColor={colors.muted} style={[styles.measureInput, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} /><Text style={[styles.measureUnit, { color: colors.muted }]}>{habit.unit || "units"}</Text></View></>}<Pressable testID="entry-save" disabled={busy || (habit.habit_type === "measurable" && !value)} onPress={save} style={[styles.primaryButton, { backgroundColor: colors.brand, opacity: busy || (habit.habit_type === "measurable" && !value) ? 0.5 : 1, marginTop: 28 }]}><Text style={styles.primaryText}>{busy ? "Saving…" : habit.habit_type === "boolean" && current?.completed ? "Clear completion" : "Save progress"}</Text></Pressable></ScrollView></KeyboardAvoidingView></View></Modal>;
}

function AddHabitModal({ colors, onClose, onCreate }: { colors: typeof lightColors; onClose: () => void; onCreate: (payload: any) => Promise<void> }) {
  const [name, setName] = useState(""); const [icon, setIcon] = useState(iconChoices[0]); const [type, setType] = useState<"boolean" | "measurable">("boolean"); const [target, setTarget] = useState(""); const [unit, setUnit] = useState(""); const [busy, setBusy] = useState(false);
  const create = async () => { if (!name.trim() || (type === "measurable" && (!target || !unit.trim()))) return; setBusy(true); try { await onCreate({ name: name.trim(), icon, habit_type: type, target: type === "measurable" ? Number(target) : null, unit: type === "measurable" ? unit.trim() : null }); } finally { setBusy(false); } };
  return <Modal transparent animationType="slide" visible onRequestClose={onClose}><View style={[styles.modalBackdrop, { backgroundColor: "rgba(0,0,0,.38)" }]}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: 24 }]}><View style={[styles.sheetHandle, { backgroundColor: colors.border }]} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetEyebrow, { color: colors.brand }]}>NEW RHYTHM</Text><Text style={[styles.sheetTitle, { color: colors.text }]}>Add a habit</Text></View><Pressable testID="add-habit-close" onPress={onClose} style={styles.iconButton}><Feather name="x" size={22} color={colors.text} /></Pressable></View><ScrollView keyboardShouldPersistTaps="handled"><TextInput testID="add-habit-name" autoFocus placeholder="Habit name" placeholderTextColor={colors.muted} value={name} onChangeText={setName} style={[styles.input, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} /><Text style={[styles.fieldLabel, { color: colors.muted }]}>Choose an icon</Text><View style={styles.iconGrid}>{iconChoices.map(choice => <Pressable testID={`habit-icon-${choice}`} key={choice} onPress={() => setIcon(choice)} style={[styles.choiceIcon, { borderColor: icon === choice ? colors.brand : colors.border, backgroundColor: icon === choice ? colors.pale : colors.bg }]}><Feather name={choice as any} size={20} color={icon === choice ? colors.brand : colors.muted} /></Pressable>)}</View><Text style={[styles.fieldLabel, { color: colors.muted }]}>How do you track it?</Text><View style={[styles.typeSwitch, { backgroundColor: colors.surface }]}><Pressable testID="habit-type-boolean" onPress={() => setType("boolean")} style={[styles.typeOption, type === "boolean" && { backgroundColor: colors.card }]}><Text style={[styles.typeText, { color: type === "boolean" ? colors.text : colors.muted }]}>Yes / No</Text></Pressable><Pressable testID="habit-type-measurable" onPress={() => setType("measurable")} style={[styles.typeOption, type === "measurable" && { backgroundColor: colors.card }]}><Text style={[styles.typeText, { color: type === "measurable" ? colors.text : colors.muted }]}>Measurable</Text></Pressable></View>{type === "measurable" && <View style={styles.measureFields}><TextInput testID="habit-target" keyboardType="decimal-pad" placeholder="Target e.g. 3" placeholderTextColor={colors.muted} value={target} onChangeText={setTarget} style={[styles.halfInput, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} /><TextInput testID="habit-unit" placeholder="Unit e.g. L" placeholderTextColor={colors.muted} value={unit} onChangeText={setUnit} style={[styles.halfInput, { color: colors.text, borderColor: colors.border, backgroundColor: colors.bg }]} /></View>}<Pressable testID="add-habit-submit" disabled={busy || !name.trim() || (type === "measurable" && (!target || !unit.trim()))} onPress={create} style={[styles.primaryButton, { backgroundColor: colors.brand, opacity: busy || !name.trim() || (type === "measurable" && (!target || !unit.trim())) ? 0.5 : 1, marginTop: 28 }]}><Text style={styles.primaryText}>{busy ? "Adding…" : "Add to dashboard"}</Text></Pressable></ScrollView></KeyboardAvoidingView></View></Modal>;
}

function MenuModal({ colors, mode, onMode, hiddenHabits, onUnhide, onLogout, onClose }: { colors: typeof lightColors; mode: ThemeMode; onMode: (m: ThemeMode) => void; hiddenHabits: Habit[]; onUnhide: (habitId: string) => void; onLogout: () => void; onClose: () => void }) {
  const themes: { key: ThemeMode; label: string; icon: any }[] = [{ key: "system", label: "System", icon: "smartphone" }, { key: "light", label: "Light", icon: "sun" }, { key: "dark", label: "Dark", icon: "moon" }];
  return <Modal transparent animationType="slide" visible onRequestClose={onClose}><View style={[styles.modalBackdrop, { backgroundColor: "rgba(0,0,0,.38)" }]}><View style={[styles.sheet, { backgroundColor: colors.card, paddingBottom: 24 }]}><View style={[styles.sheetHandle, { backgroundColor: colors.border }]} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetEyebrow, { color: colors.brand }]}>MENU</Text><Text style={[styles.sheetTitle, { color: colors.text }]}>Settings</Text></View><Pressable testID="menu-close" onPress={onClose} style={styles.iconButton}><Feather name="x" size={22} color={colors.text} /></Pressable></View><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ paddingBottom: 12 }}><Text style={[styles.fieldLabel, { color: colors.muted }]}>Appearance</Text><View style={[styles.typeSwitch, { backgroundColor: colors.surface }]}>{themes.map(theme => <Pressable key={theme.key} testID={`theme-${theme.key}`} onPress={() => onMode(theme.key)} style={[styles.typeOption, mode === theme.key && { backgroundColor: colors.card }]}><Feather name={theme.icon} size={14} color={mode === theme.key ? colors.text : colors.muted} /><Text style={[styles.typeText, { color: mode === theme.key ? colors.text : colors.muted, marginLeft: 6 }]}>{theme.label}</Text></Pressable>)}</View><Text style={[styles.fieldLabel, { color: colors.muted, marginTop: 18 }]}>Hidden habits</Text>{hiddenHabits.length === 0 ? <View style={[styles.hiddenEmpty, { borderColor: colors.border }]}><Feather name="eye" size={16} color={colors.muted} /><Text style={[styles.hiddenEmptyText, { color: colors.muted }]}>No habits are hidden.</Text></View> : hiddenHabits.map(habit => <View key={habit.habit_id} style={[styles.hiddenRow, { borderColor: colors.border, backgroundColor: colors.bg }]}><View style={[styles.habitIcon, { backgroundColor: colors.pale, width: 34, height: 34, borderRadius: 11 }]}><Feather name={habit.icon as any} size={15} color={colors.brand} /></View><Text numberOfLines={1} style={[styles.hiddenName, { color: colors.text }]}>{habit.name}</Text><Pressable testID={`unhide-${habit.habit_id}`} onPress={() => onUnhide(habit.habit_id)} style={[styles.unhideBtn, { backgroundColor: colors.pale }]}><Text style={[styles.unhideText, { color: colors.brand }]}>Unhide</Text></Pressable></View>)}<Pressable testID="menu-logout" onPress={onLogout} style={[styles.menuLogout, { borderColor: colors.border }]}><Feather name="log-out" size={16} color={colors.red} /><Text style={[styles.menuLogoutText, { color: colors.red }]}>Sign out</Text></Pressable></ScrollView></View></View></Modal>;
}

function Dashboard({ user, token, onLogout, mode, onMode, colors }: { user: User; token: string; onLogout: () => void; mode: ThemeMode; onMode: (m: ThemeMode) => void; colors: typeof lightColors }) {
  const insets = useSafeAreaInsets(); const [habits, setHabits] = useState<Habit[]>([]); const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [error, setError] = useState(""); const [addOpen, setAddOpen] = useState(false); const [menuOpen, setMenuOpen] = useState(false); const [selected, setSelected] = useState<{ habit: Habit; date: Date } | null>(null); const [months, setMonths] = useState<Record<string, Date>>({}); const [dragging, setDragging] = useState<string | null>(null);
  const load = useCallback(async (soft = false) => { if (soft) setRefreshing(true); else setLoading(true); setError(""); try { setHabits(await api("/habits", {}, token)); } catch (err) { setError(err instanceof Error ? err.message : "Unable to load habits"); } finally { setLoading(false); setRefreshing(false); } }, [token]);
  useEffect(() => { load(); }, [load]);
  const updateEntry = async (value: number | boolean) => { if (!selected) return; const { habit, date } = selected; try { const updated = await api(`/habits/${habit.habit_id}/entries`, { method: "PUT", body: JSON.stringify({ date: dateKey(date), ...(habit.habit_type === "boolean" ? { completed: value } : { value }) }) }, token); setHabits(current => current.map(item => item.habit_id !== habit.habit_id ? item : { ...item, entries: updated.deleted ? item.entries.filter(entry => entry.date !== updated.date) : [...item.entries.filter(entry => entry.date !== updated.date), updated] })); setSelected(null); } catch (err) { Alert.alert("Could not save", err instanceof Error ? err.message : "Try again"); } };
  const toggleBoolean = async (habit: Habit, date: Date) => { const key = dateKey(date); const current = habit.entries.find(entry => entry.date === key); try { const updated = await api(`/habits/${habit.habit_id}/entries`, { method: "PUT", body: JSON.stringify({ date: key, completed: !current?.completed }) }, token); setHabits(items => items.map(item => item.habit_id !== habit.habit_id ? item : { ...item, entries: updated.deleted ? item.entries.filter(entry => entry.date !== key) : [...item.entries.filter(entry => entry.date !== key), updated] })); } catch (err) { Alert.alert("Could not save", err instanceof Error ? err.message : "Try again"); } };
  const createHabit = async (payload: any) => { try { const created = await api("/habits", { method: "POST", body: JSON.stringify(payload) }, token); setHabits(current => [...current, created]); setAddOpen(false); } catch (err) { Alert.alert("Could not add habit", err instanceof Error ? err.message : "Try again"); } };
  const moveHabit = async (habitId: string, delta: number) => { const index = habits.findIndex(habit => habit.habit_id === habitId); const next = index + delta; if (index < 0 || next < 0 || next >= habits.length) return; const ordered = [...habits]; [ordered[index], ordered[next]] = [ordered[next], ordered[index]]; setHabits(ordered); setDragging(null); try { await api("/habits/reorder", { method: "PATCH", body: JSON.stringify(ordered.map(habit => habit.habit_id)) }, token); } catch { load(true); } };
  const setHidden = async (habitId: string, hidden: boolean) => { const prev = habits; setHabits(items => items.map(item => item.habit_id === habitId ? { ...item, hidden } : item)); try { await api(`/habits/${habitId}`, { method: "PATCH", body: JSON.stringify({ hidden }) }, token); } catch (err) { setHabits(prev); Alert.alert("Could not update", err instanceof Error ? err.message : "Try again"); } };
  const deleteHabit = async (habit: Habit) => { const confirm = () => { const prev = habits; setHabits(items => items.filter(item => item.habit_id !== habit.habit_id)); api(`/habits/${habit.habit_id}`, { method: "DELETE" }, token).catch(err => { setHabits(prev); Alert.alert("Could not delete", err instanceof Error ? err.message : "Try again"); }); }; Alert.alert("Delete habit", `Delete "${habit.name}" and all its entries?`, [{ text: "Cancel", style: "cancel" }, { text: "Delete", style: "destructive", onPress: confirm }]); };
  const visibleHabits = habits.filter(habit => !habit.hidden);
  const hiddenHabits = habits.filter(habit => habit.hidden);
  if (loading) return <View style={[styles.center, { backgroundColor: colors.bg }]}><ActivityIndicator color={colors.brand} /><Text style={[styles.loadingText, { color: colors.muted }]}>Loading your rhythms…</Text></View>;
  // @ts-ignore Native refresh props are accepted by the platform ScrollView implementation.
  return <View style={[styles.dashboardRoot, { backgroundColor: colors.bg, paddingTop: insets.top + 18, paddingBottom: insets.bottom }]}><View style={[styles.header, { paddingHorizontal: 14 }]}><Image source={{ uri: TICK_IT_LOGO }} style={styles.headerLogo} /><View style={styles.headerTitleWrap}><Text style={[styles.eyebrow, { color: colors.brand }]}>TICK IT</Text><Text numberOfLines={1} style={[styles.dashboardTitle, { color: colors.text }]}>Good morning, {user.name.split(" ")[0]}.</Text></View><View style={styles.headerActions}><Pressable testID="menu-open" accessibilityLabel="Open menu" onPress={() => setMenuOpen(true)} style={[styles.circleButton, { width: 40, height: 40, backgroundColor: colors.card, borderColor: colors.border }]}><Feather name="menu" size={18} color={colors.text} /></Pressable></View></View><View style={styles.subHeader}><Text style={[styles.subTitle, { color: colors.muted }]}>{visibleHabits.length ? `${visibleHabits.length} ${visibleHabits.length === 1 ? "habit" : "habits"} in motion` : "A fresh page for your habits"}</Text><Pressable testID="add-habit" onPress={() => setAddOpen(true)} style={({ pressed }) => [styles.addSmall, { backgroundColor: colors.brand, opacity: pressed ? 0.75 : 1 }]}><Feather name="plus" size={16} color="#FFF" /><Text style={styles.addSmallText}>Add habit</Text></Pressable></View>{!!error && <Pressable onPress={() => load()} style={[styles.errorBanner, { backgroundColor: colors.pale }]}><Text style={[styles.errorBannerText, { color: colors.brand }]}>{error} · Tap to retry</Text></Pressable>}<ScrollView contentContainerStyle={styles.dashboardContent} showsVerticalScrollIndicator={false} refreshing={refreshing} onRefresh={() => load(true)}>{visibleHabits.length === 0 ? <View style={[styles.empty, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.emptyIcon, { backgroundColor: colors.pale }]}><Feather name="layers" size={25} color={colors.brand} /></View><Text style={[styles.emptyTitle, { color: colors.text }]}>Start with one small rhythm.</Text><Text style={[styles.emptyText, { color: colors.muted }]}>Your monthly calendars will collect here, one below the next.</Text><Pressable testID="add-first-habit" onPress={() => setAddOpen(true)} style={[styles.primaryButton, { backgroundColor: colors.brand, marginTop: 20 }]}><Text style={styles.primaryText}>Add your first habit</Text></Pressable></View> : visibleHabits.map(habit => <HabitCard key={habit.habit_id} habit={habit} colors={colors} month={months[habit.habit_id] || new Date()} onMonthChange={month => setMonths(current => ({ ...current, [habit.habit_id]: month }))} onDayPress={date => { if (habit.habit_type === "boolean") toggleBoolean(habit, date); else setSelected({ habit, date }); }} onReorder={delta => moveHabit(habit.habit_id, delta)} isReordering={dragging === habit.habit_id} onHide={() => setHidden(habit.habit_id, true)} onDelete={() => deleteHabit(habit)} />)}<Pressable testID="add-another-habit" onPress={() => setAddOpen(true)} style={[styles.bottomAdd, { borderColor: colors.border, backgroundColor: colors.card }]}><Feather name="plus" size={18} color={colors.brand} /><Text style={[styles.bottomAddText, { color: colors.brand }]}>Add another habit</Text></Pressable><Text style={[styles.madeNote, { color: colors.muted }]}>A little greener, every day.</Text></ScrollView>{selected && <EntryModal habit={selected.habit} date={selected.date} colors={colors} onClose={() => setSelected(null)} onSave={updateEntry} />}{addOpen && <AddHabitModal colors={colors} onClose={() => setAddOpen(false)} onCreate={createHabit} />}{menuOpen && <MenuModal colors={colors} mode={mode} onMode={onMode} hiddenHabits={hiddenHabits} onUnhide={id => setHidden(id, false)} onLogout={() => { setMenuOpen(false); onLogout(); }} onClose={() => setMenuOpen(false)} />}</View>;
}

export default function Index() {
  const systemScheme = useColorScheme(); const [user, setUser] = useState<User | null>(null); const [token, setToken] = useState<string | null>(null); const [booting, setBooting] = useState(true); const [mode, setMode] = useState<ThemeMode>("system");
  useEffect(() => { (async () => { const savedMode = await AsyncStorage.getItem(THEME_KEY); if (savedMode === "light" || savedMode === "dark" || savedMode === "system") setMode(savedMode); const savedToken = await storage.getToken(); if (savedToken) { try { const data = await api("/auth/me", {}, savedToken); setToken(savedToken); setUser(data.user); } catch { await storage.clearToken(); } } setBooting(false); })(); }, []);
  const colors = mode === "dark" || (mode === "system" && systemScheme === "dark") ? darkColors : lightColors;
  const changeMode = async (next: ThemeMode) => { setMode(next); await AsyncStorage.setItem(THEME_KEY, next); };
  const logout = async () => { await storage.clearToken(); setToken(null); setUser(null); };
  if (booting) return <View style={[styles.center, { backgroundColor: colors.bg }]}><View style={[styles.logoMark, { backgroundColor: colors.brand }]}><Feather name="activity" size={24} color="#FFF" /></View><ActivityIndicator color={colors.brand} style={{ marginTop: 16 }} /></View>;
  return <GestureHandlerRootView style={{ flex: 1 }}>{user && token ? <Dashboard user={user} token={token} onLogout={logout} mode={mode} onMode={changeMode} colors={colors} /> : <AuthScreen onAuthenticated={data => { setToken(data.session_token); setUser(data.user); }} colors={colors} />}</GestureHandlerRootView>;
}

